
"""Constrained model output schema for LLM-generated assessments."""

from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    field_validator,
)

from app.models.assessment import AssessmentStatus, FindingSeverity


class DraftFinding(BaseModel):
    """A finding generated by the LLM before evidence resolution."""

    model_config = ConfigDict(extra="forbid")

    title: str = Field(description="Short finding title.")
    description: str = Field(description="Evidence-grounded explanation.")
    severity: FindingSeverity = FindingSeverity.UNKNOWN
    evidence_ids: list[str] = Field(default_factory=list)

    @field_validator("title", "description")
    @classmethod
    def text_must_not_be_blank(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("Finding text must not be blank.")
        return value.strip()


class LLMAssessmentDraft(BaseModel):
    """
    Internal LLM output contract.

    Evidence references and URLs are deliberately excluded.
    The application resolves all evidence IDs against retrieved
    documents before constructing the public UpgradeAssessment.
    """

    model_config = ConfigDict(extra="forbid")

    status: AssessmentStatus
    summary: str = Field(description="Overall upgrade assessment summary.")

    evidence_ids: list[str] = Field(default_factory=list)

    compatibility_findings: list[DraftFinding] = Field(default_factory=list)
    breaking_changes: list[DraftFinding] = Field(default_factory=list)
    migration_concerns: list[DraftFinding] = Field(default_factory=list)
    security_findings: list[DraftFinding] = Field(default_factory=list)

    limitations: list[str] = Field(default_factory=list)

    @field_validator("summary")
    @classmethod
    def summary_must_contain_non_whitespace(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("Summary must not be blank.")
        return value.strip()
